"""Module holding the implementation for providing Emil log specific log file.
"""
import zipfile
import os


class ClassicalGnbEmilLogFileProvider:
    """Class to get the trace file for emil logs. Currently the output format 5gm is supported.
    """

    def get_emil_log_file(self, log_directory, collector_config):
        """Determines the location of the dcap.zip file and unpacks the containing 5gm files. The path to the
        unpacked 5gm file is returnd.

        :param str log_directory: the path where the log files of the collector are stored
        :param str collector_config: the collector configuration of the collector to obtain additional information
        """
        dcap_zip_file = os.path.join(log_directory, 'dcap.zip')

        with zipfile.ZipFile(file=dcap_zip_file) as dcap_zip:

            log_files_5gm = [filename for filename in dcap_zip.namelist() if filename.endswith("5gm")]

            for log_file in log_files_5gm:
                dcap_zip.extract(log_file, log_directory)

        return [os.path.join(log_directory, log_file) for log_file in log_files_5gm]
